using AudioGuide.Business;
using AudioGuide.Data;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.Extensions.FileProviders;
using Microsoft.IdentityModel.Tokens;
using Serilog;
using System.Text;
using System.Threading.RateLimiting;
var b = WebApplication.CreateBuilder(args);
b.Services.AddScoped<FallbackSpeechService>();
var secret = b.Configuration["JWT_SECRET"] ?? throw new Exception("Cần JWT_SECRET (ít nhất 32 ký tự)"); if (secret.Length < 32) throw new Exception("JWT_SECRET cần ít nhất 32 ký tự");
b.Host.UseSerilog((ctx, c) => c.MinimumLevel.Override("Microsoft", Serilog.Events.LogEventLevel.Warning).WriteTo.Console());
var conn = b.Configuration["DB_CONNECTION"] ?? throw new Exception("Cần DB_CONNECTION");
b.Services.AddDbContext<AppDbContext>(o => o.UseMySql(conn, new MySqlServerVersion(new Version(8, 0, 0))));
b.Services.AddScoped<IRepository, Repository>(); b.Services.AddScoped<IGuideService, GuideService>(); b.Services.AddScoped<IGeofenceService, GeofenceService>(); b.Services.AddScoped<IAuthService, AuthService>(); b.Services.AddScoped<IMediaService, MediaService>(); b.Services.AddHttpClient();
b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new() { ValidateIssuer = true, ValidateAudience = true, ValidateLifetime = true, ValidateIssuerSigningKey = true, ValidIssuer = "saigon-guide", ValidAudience = "saigon-guide", IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)), ClockSkew = TimeSpan.FromSeconds(30) });
b.Services.AddAuthorization(o => { o.AddPolicy("Editor", p => p.RequireRole("Admin", "Editor")); o.AddPolicy("Admin", p => p.RequireRole("Admin")); });
b.Services.AddCors(o => o.AddDefaultPolicy(p => p.WithOrigins((b.Configuration["CORS_ORIGINS"] ?? "http://localhost:5173,http://localhost:8080").Split(',')).AllowAnyHeader().AllowAnyMethod()));
b.Services.AddRateLimiter(o => { o.RejectionStatusCode = 429; o.AddPolicy("public", c => RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString() ?? "local", _ => new() { PermitLimit = 180, Window = TimeSpan.FromMinutes(1), QueueLimit = 0 })); o.AddPolicy("login", c => RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString() ?? "local", _ => new() { PermitLimit = 8, Window = TimeSpan.FromMinutes(1), QueueLimit = 0 })); o.OnRejected = async (c, t) => { c.HttpContext.Response.ContentType = "application/json"; await c.HttpContext.Response.WriteAsJsonAsync(new { status = 429, code = "RATE_LIMIT", message = "Thao tác quá nhanh, vui lòng thử lại sau.", errors = Array.Empty<string>() }, t); }; });
b.Services.Configure<Microsoft.AspNetCore.Http.Json.JsonOptions>(o => o.SerializerOptions.ReferenceHandler = System.Text.Json.Serialization.ReferenceHandler.IgnoreCycles);
b.Services.AddEndpointsApiExplorer(); b.Services.AddSwaggerGen();
var app = b.Build();
app.Use(async (c, next) => { try { c.Response.Headers["X-Content-Type-Options"] = "nosniff"; await next(); } catch (Exception ex) { var status = ex is AppError ae ? ae.Status : ex is BadHttpRequestException ? 400 : 500; Log.Error("Request failed: {Type} {Path}", ex.GetType().Name, c.Request.Path); c.Response.StatusCode = status; await c.Response.WriteAsJsonAsync(new { status, code = status == 500 ? "SERVER_ERROR" : status == 409 ? "CONFLICT" : "REQUEST_ERROR", message = status == 500 ? "Lỗi hệ thống. Vui lòng thử lại." : ex is BadHttpRequestException ? "Dữ liệu gửi lên không hợp lệ" : ex.Message, errors = Array.Empty<string>() }); } });
app.UseSerilogRequestLogging(); app.UseCors(); app.UseRateLimiter(); app.UseAuthentication(); app.UseAuthorization();
var media = Path.GetFullPath(b.Configuration["MEDIA_PATH"] ?? "media"); Directory.CreateDirectory(media); app.UseStaticFiles(new StaticFileOptions { FileProvider = new PhysicalFileProvider(media), RequestPath = "/media" });
app.UseSwagger(); app.UseSwaggerUI();
using (var scope = app.Services.CreateScope()) { await Seed.Run(scope.ServiceProvider.GetRequiredService<AppDbContext>(), b.Configuration["ADMIN_USERNAME"] ?? "admin", b.Configuration["ADMIN_PASSWORD"] ?? ""); }
app.MapGet("/health", async (AppDbContext db) => await db.Database.CanConnectAsync() ? Results.Ok(new { status = "ok" }) : Results.StatusCode(503));
var api = app.MapGroup("/api").RequireRateLimiting("public");
api.AddEndpointFilter<RequestValidation>();
api.MapGet("/languages", (IGuideService s) => s.Languages());
api.MapGet("/locations", (string? lang, IGuideService s) => s.Locations(lang ?? "vi"));
api.MapGet("/locations/nearby", async (double lat, double lng, double acc, IGeofenceService geo, IRepository r) => geo.Nearby(await r.Db.Locations.AsNoTracking().Where(x => x.IsActive).ToListAsync(), lat, lng, acc));
api.MapGet("/locations/{id:int}/narration", (int id, string? lang, IGuideService s) => s.Narration(id, lang ?? "vi"));
api.MapPost("/locations/{id:int}/speech", async (int id, string lang, IGuideService guide, FallbackSpeechService speech) =>
{
    var narration = await guide.Narration(id, lang);
    return new { url = narration.AudioUrl ?? await speech.Generate(narration) };
});
api.MapPost("/playlogs", async (PlayLog p, IGuideService s) => Results.Ok(new { id = await s.Log(p) }));
api.MapPut("/playlogs/{id:long}/complete", async (long id, CompleteRequest p, IGuideService s) => { await s.Complete(id, p.SessionId); return Results.NoContent(); });
api.MapPost("/feedbacks", async (Feedback p, IGuideService s) => { await s.Feedback(p); return Results.Created("/api/feedbacks", new { message = "Cảm ơn phản hồi của bạn" }); });
app.MapPost("/api/auth/login", (LoginRequest p, IAuthService s) => s.Login(p)).RequireRateLimiting("login");
var admin = api.MapGroup("/admin").RequireAuthorization("Editor");
admin.AddEndpointFilter(async (ctx, next) => { var result = await next(ctx); if (ctx.HttpContext.Request.Method != "GET") { var s = ctx.HttpContext.RequestServices.GetRequiredService<IGuideService>(); await s.Audit(ctx.HttpContext.User.Identity?.Name ?? "unknown", ctx.HttpContext.Request.Method + " " + ctx.HttpContext.Request.Path); } return result; });
admin.MapGet("/locations", (IGuideService s) => s.Locations("vi", true)); admin.MapPost("/locations", (Location p, IGuideService s) => s.SaveLocation(0, p)); admin.MapPut("/locations/{id:int}", (int id, Location p, IGuideService s) => s.SaveLocation(id, p)); admin.MapDelete("/locations/{id:int}", async (int id, IGuideService s) => { await s.DeleteLocation(id); return Results.NoContent(); }).RequireAuthorization("Admin");
admin.MapGet("/languages", (IGuideService s) => s.Languages(true)); admin.MapPost("/languages", (Language p, IGuideService s) => s.SaveLanguage(0, p)).RequireAuthorization("Admin"); admin.MapPut("/languages/{id:int}", (int id, Language p, IGuideService s) => s.SaveLanguage(id, p)).RequireAuthorization("Admin"); admin.MapDelete("/languages/{id:int}", async (int id, IGuideService s) => { await s.DeleteLanguage(id); return Results.NoContent(); }).RequireAuthorization("Admin");
admin.MapGet("/translations", (IGuideService s) => s.Translations()); admin.MapPost("/translations", (LocationTranslation p, IGuideService s, HttpContext c) => s.SaveTranslation(0, p, c.User.IsInRole("Admin"))); admin.MapPut("/translations/{id:int}", (int id, LocationTranslation p, IGuideService s, HttpContext c) => s.SaveTranslation(id, p, c.User.IsInRole("Admin"))); admin.MapDelete("/translations/{id:int}", async (int id, IGuideService s) => { await s.DeleteTranslation(id); return Results.NoContent(); }).RequireAuthorization("Admin");
admin.MapPost("/translations/auto-translate", (TranslateRequest p, IMediaService s) => s.Translate(p.LocationId, p.LanguageId));
admin.MapPost("/audio/generate", async (AudioRequest p, IMediaService s) => new { url = await s.Generate(p.TranslationId) });
admin.MapPost("/audio/upload", async (HttpRequest req, IMediaService s) => { if (!req.HasFormContentType || req.ContentLength > 21 * 1024 * 1024) throw new AppError(400, "Cần multipart audio dưới 20 MB"); var form = await req.ReadFormAsync(); if (!int.TryParse(form["translationId"], out var id) || form.Files.Count != 1 || form.Files[0].Length > 20 * 1024 * 1024) throw new AppError(400, "Thiếu translationId/file hoặc file quá lớn"); using var ms = new MemoryStream(); await form.Files[0].CopyToAsync(ms); return new { url = await s.Upload(id, ms.ToArray()) }; }).DisableAntiforgery();
admin.MapGet("/statistics", (IGuideService s) => s.Statistics()); admin.MapGet("/logs", async (IRepository r) => await r.Db.AuditLogs.AsNoTracking().OrderByDescending(x => x.CreatedAt).Take(200).ToListAsync());
admin.MapPost("/users", async (UserRequest p, IRepository r) => { if (p.Username.Length < 3 || p.Username.Length > 100 || p.Password.Length < 12 || p.Password.Length > 100 || !(p.Role is "Admin" or "Editor")) throw new AppError(400, "Tên ≥3 ký tự, mật khẩu 12–100 ký tự, vai trò Admin/Editor"); if (await r.Db.AdminUsers.AnyAsync(x => x.Username == p.Username)) throw new AppError(409, "Tên đăng nhập đã tồn tại"); r.Db.AdminUsers.Add(new() { Username = p.Username, PasswordHash = BCrypt.Net.BCrypt.HashPassword(p.Password), Role = p.Role, FullName = p.FullName }); await r.Save(); return Results.Ok(new { message = "Đã tạo tài khoản" }); }).RequireAuthorization("Admin");
app.Run();
record CompleteRequest(string SessionId); record TranslateRequest(int LocationId, int LanguageId); record AudioRequest(int TranslationId); record UserRequest(string Username, string Password, string Role, string FullName);
